use std::collections::hash_map::DefaultHasher;use std::hash::{Hash, Hasher};pub fn digest(input: String) -> String {    let mut hasher = DefaultHasher::new();    input.hash(&mut hasher);    let hash = hasher.finish();    format!(        "{:016x}{:016x}{:016x}{:016x}",        hash,        hash.wrapping_mul(31),        hash.wrapping_mul(131),        hash.wrapping_mul(313)    )}